//! Deterministic, uncompressed ZIP files. Reject ZIP64-sized inputs rather than
//! emitting truncated archives. All file names are generated by the program.
use std::{
    fs,
    io::{BufWriter, Write},
    path::Path,
};
fn u16le(out: &mut impl Write, v: u16) -> std::io::Result<()> {
    out.write_all(&v.to_le_bytes())
}
fn u32le(out: &mut impl Write, v: u32) -> std::io::Result<()> {
    out.write_all(&v.to_le_bytes())
}
fn collect(root: &Path, dir: &Path, files: &mut Vec<String>) -> Result<(), String> {
    for item in fs::read_dir(dir).map_err(|e| e.to_string())? {
        let item = item.map_err(|e| e.to_string())?;
        let p = item.path();
        let ty = item.file_type().map_err(|e| e.to_string())?;
        if ty.is_symlink() {
            return Err("symlink in pack tree".into());
        }
        if ty.is_dir() {
            collect(root, &p, files)?;
        } else if ty.is_file() {
            let name = p
                .strip_prefix(root)
                .map_err(|e| e.to_string())?
                .to_str()
                .ok_or("non-UTF8 path")?
                .replace('\\', "/");
            files.push(name);
        }
    }
    Ok(())
}
pub fn write(root: &Path, destination: &Path) -> Result<(), String> {
    let mut files = Vec::new();
    collect(root, root, &mut files)?;
    files.sort();
    let count = u16::try_from(files.len()).map_err(|_| "ZIP64 not supported")?;
    let file = fs::File::create(destination).map_err(|e| e.to_string())?;
    let mut out = BufWriter::new(file);
    let mut position: u64 = 0;
    let mut entries = Vec::new();
    for name in files {
        let data = fs::read(root.join(&name)).map_err(|e| e.to_string())?;
        let len = u32::try_from(data.len()).map_err(|_| "ZIP64 not supported")?;
        let offset = u32::try_from(position).map_err(|_| "ZIP64 not supported")?;
        let n = u16::try_from(name.len()).map_err(|_| "ZIP name too long")?;
        let mut hasher = crc32fast::Hasher::new();
        hasher.update(&data);
        let crc = hasher.finalize();
        let result: std::io::Result<()> = (|| {
            u32le(&mut out, 0x04034b50)?;
            u16le(&mut out, 20)?;
            u16le(&mut out, 0x800)?;
            u16le(&mut out, 0)?;
            u16le(&mut out, 0)?;
            u16le(&mut out, 0x21)?;
            u32le(&mut out, crc)?;
            u32le(&mut out, len)?;
            u32le(&mut out, len)?;
            u16le(&mut out, n)?;
            u16le(&mut out, 0)?;
            out.write_all(name.as_bytes())?;
            out.write_all(&data)
        })();
        result.map_err(|e| e.to_string())?;
        position += 30 + u64::from(n) + u64::from(len);
        entries.push((name, n, crc, len, offset));
    }
    let central_offset = u32::try_from(position).map_err(|_| "ZIP64 not supported")?;
    for (name, n, crc, len, offset) in entries {
        let result: std::io::Result<()> = (|| {
            u32le(&mut out, 0x02014b50)?;
            u16le(&mut out, 20)?;
            u16le(&mut out, 20)?;
            u16le(&mut out, 0x800)?;
            u16le(&mut out, 0)?;
            u16le(&mut out, 0)?;
            u16le(&mut out, 0x21)?;
            u32le(&mut out, crc)?;
            u32le(&mut out, len)?;
            u32le(&mut out, len)?;
            u16le(&mut out, n)?;
            u16le(&mut out, 0)?;
            u16le(&mut out, 0)?;
            u16le(&mut out, 0)?;
            u16le(&mut out, 0)?;
            u32le(&mut out, 0)?;
            u32le(&mut out, offset)?;
            out.write_all(name.as_bytes())
        })();
        result.map_err(|e| e.to_string())?;
        position += 46 + u64::from(n);
    }
    let size =
        u32::try_from(position - u64::from(central_offset)).map_err(|_| "ZIP64 not supported")?;
    let result: std::io::Result<()> = (|| {
        u32le(&mut out, 0x06054b50)?;
        u16le(&mut out, 0)?;
        u16le(&mut out, 0)?;
        u16le(&mut out, count)?;
        u16le(&mut out, count)?;
        u32le(&mut out, size)?;
        u32le(&mut out, central_offset)?;
        u16le(&mut out, 0)?;
        out.flush()
    })();
    result.map_err(|e| e.to_string())
}
